    /// <summary>
    /// Backend implementation that wires up the Bohris data source, factory, and
    /// renderer into the ASP.NET Core DI container.
    /// </summary>
    public class Backend : IBovisBackend
    {
        /// <summary>
        /// Configures the service collection with required Bohris services.
        /// </summary>
        /// <param name="services">The <see cref="IServiceCollection"/> to which services are added.</param>
        /// <param name="configStore">Configuration store providing runtime settings.</param>
        /// <param name="connection">Database connection used by the data source.</param>
        /// <param name="dataInit">Optional initialization script or data for the data source.</param>
        public void Setup(IServiceCollection services, IConfigurationStore configStore, DbConnection connection, string? dataInit)
        {
            // Declare variables for the data source and factory.
            Bovis.Interfaces.IBovisDataSource dataSource;
            IBovisFactory bovisFactory;

            // Create the renderer with the provided configuration store.
            BohrlochRenderer bohrlochRenderer = new BohrlochRenderer(configStore);

            // Initialize the data source with the DB connection, configuration, and optional init data.
            dataSource = new BohrisDataSource(connection, configStore, dataInit);

            // Instantiate the Bohris-specific factory.
            bovisFactory = new Bovis.Services.Bohris.Factory();

            // Ensure the data source opens its connection immediately.
            dataSource.ForceOpen();

            // Register the data source, factory, and renderer as singletons in the DI container.
            services.AddSingleton<Bovis.Interfaces.IBovisDataSource>(dataSource);
            services.AddSingleton<Bovis.Interfaces.IBovisFactory>(bovisFactory);
            services.AddSingleton<BohrlochRenderer>(bohrlochRenderer);
        }
        IFieldInfos IBovisBackend.FieldInfos => FieldInfos.LoadFieldInfos("Bovis.Data.Bohris/columnhelp.json");
    }
}

