using DbTools.DbUrl;

namespace Bovis.Data.Bohris.Test
{
    /// <summary>
    /// Base class for decoder unit tests. Inherits from <see cref="Bovis.TestProfile.TestClassCommon"/>
    /// and provides a shared decoder instance (<c>m_decoder</c>) initialized with a
    /// temporary in‑memory storage connection.
    /// </summary>
    public class TestDecoderBase : Bovis.TestProfile.TestClassCommon
    {
        /// <summary>
        /// Decoder instance used by derived test classes. May be <c>null</c> until
        /// initialized in <see cref="BaseInit"/>.
        /// </summary>
        internal IKuerzelDecoder? m_decoder;

        /// <summary>
        /// Initializes the test environment. Creates a connection to the BohrIs
        /// database, opens it, and constructs a <see cref="Bohris.BohrisShortCodeDecoder"/>
        /// using both the BohrIs connection and an in‑memory storage connection.
        /// </summary>
        [TestInitialize]
        public void BaseInit()
        {
            // Build a connection URL from the configuration.
            var url = new ConnectionUrl(TestProfile.Config.BohrIsUrl);
            // Create and open a connection to the BohrIs database.
            using var conn = url.CreateConnection();
            conn.Open();

            // Initialize the decoder with the BohrIs connection and an in‑memory storage.
            m_decoder = new Bohris.BohrisShortCodeDecoder(
                conn,
                Bovis.Storage.Storage.OpenStorageFile(":memory:").Connection);

            // Explicitly dispose the BohrIs connection (handled by using statement as well).
            conn.Dispose();
        }
    }
