    /// <summary>
    /// Backend implementation of <see cref="IBovisBackend"/> for the LBEG module.
    /// Sets up dependency injection services, data source, factory, and renderer.
    /// </summary>
    public class Backend : IBovisBackend
    {
        /// <summary>
        /// Configures the required services for the LBEG backend.
        /// </summary>
        /// <param name="services">The service collection to which dependencies are added.</param>
        /// <param name="configStore">Configuration store providing application settings.</param>
        /// <param name="connection">Database connection used by the data source.</param>
        /// <param name="dataInit">Optional initialization data for the data source.</param>
        public void Setup(IServiceCollection services, IConfigurationStore configStore, DbConnection connection, string? dataInit)
        {
            Bovis.Interfaces.IBovisDataSource dataSource;
            IBovisFactory bovisFactory;
            // Initialize the renderer with the provided configuration store.
            BohrlochRenderer bohrlochRenderer = new BohrlochRenderer(configStore);

            // Create the LBEG data source using the database connection and optional init data.
            dataSource = new LBEGDataSource(connection, configStore, dataInit);
            // Instantiate the factory specific to the LBEG implementation.
            bovisFactory = new Bovis.Services.LBEG.Factory();

            // The LBEG Renderer uses a custom Skia symbol renderer.
            // Assign the custom Skia symbol renderer to the BohrlochRenderer.
            bohrlochRenderer.SymbolRenderer = new Bovis.Services.LBEG.Renderer.SkiaLBEGSymbolRenderer();

            // Ensure the data source opens its underlying connection.
            dataSource.ForceOpen();

            // Register singleton services for dependency injection.
            services.AddSingleton<Bovis.Interfaces.IBovisDataSource>(dataSource);
            services.AddSingleton<Bovis.Interfaces.IBovisFactory>(bovisFactory);
            services.AddSingleton<BohrlochRenderer>(bohrlochRenderer);
        }
        IFieldInfos IBovisBackend.FieldInfos => FieldInfos.LoadFieldInfos("Bovis.Data.LBEG/columnhelp.json"); 
    }
