// -----------------------------------------------------------------------------
// PublicRouteAttribute.cs
// -----------------------------------------------------------------------------
// Defines a custom route attribute that prefixes routes with a globally defined
// public base URL, allowing controllers to expose endpoints without requiring
// authentication.
// -----------------------------------------------------------------------------
using Microsoft.AspNetCore.Mvc;

namespace Bovis.Web.Views
{
    /// <summary>
    /// Specifies that the route is a public route that can be accessed without authentication.
    /// The attribute works by adding <c>Globals.PublicBaseUrl</c> to the beginning of the route path.
    /// </summary>
    [AttributeUsage(AttributeTargets.Class, AllowMultiple = false, Inherited = true)]
    public class PublicRouteAttribute : RouteAttribute
    {
        /// <summary>
        /// Initializes a new instance of the <see cref="PublicRouteAttribute"/> class with the specified route.
        /// </summary>
        /// <param name="route">
        /// The route template provided by the developer. This value is appended to <c>Globals.PublicBaseUrl</c>.
        /// </param>
        public PublicRouteAttribute(string route) : base(GetPublicRoute(route))
        {
        }

        /// <summary>
        /// Constructs the full public route by combining the global public base URL with the supplied route template.
        /// </summary>
        /// <param name="route">The developer‑specified route template.</param>
        /// <returns>A normalized route string that starts with the public base URL.</returns>
        private static string GetPublicRoute(string route)
        {
            // Combine the global public base URL with the provided route.
            string r = $"{Globals.PublicBaseUrl}/{route}";
            // Replace any accidental double slashes with a single slash to ensure a valid URL.
            return r.Replace("//", "/");
        }
    }
}

